  (319, 'Blood Shield', 'Spell_Shadow_SacrificialShield', 'Strikes the 3 nearest enemies within 8 yards for damage and heals you for 0.5% of your maximum health per enemy hit, up to 2.5%. Deals 50% more damage while Enraged. Healing past full health becomes a Blood Shield that explodes for 200% damage within 8 yards when it breaks.', 23881, 0, 2000, 10, 8, 1.1, 1, 0, 0, 304, 0.5, 0, 0, 34, 2, 0, 3, 0, 0, 1, 0, 0, 262144, 0, 0, 0, 0, 0),
  (320, 'Bloodbath', 'Spell_Shadow_DeathPact', 'Strikes the 3 nearest enemies within 8 yards for damage and heals you for 0.5% of your maximum health per enemy hit, up to 2.5%. Deals 50% more damage while Enraged. Below 50% health it strikes all enemies within 8 yards instead and heals up to 4%.', 23881, 0, 2000, 10, 0, 1.1, 1, 0, 0, 304, 0.5, 0, 0, 34, 0, 0, 3, 0, 0, 1, 0, 0, 524288, 0, 0, 0, 0, 0),
  (321, 'Chain Execution', 'Ability_Warrior_PunishingBlow', 'Strikes all enemies within 8 yards of you for damage. Normal enemies below 20% health die instantly; elites and bosses below 20% take triple damage. Its kills explode for 50% damage within 5 yards, executing normal enemies left below 20%. Kills Enrage you.', 24316, 1, 2500, 10, 10, 1, 1, 0, 0, 305, 0, 0, 0, 11, 20, 0, 1, 0, 0, 3, 0, 20, 1048576, 0, 0, 0, 0, 0),
  (322, 'Sweep', 'INV_Axe_09', 'Strikes all enemies within 8 yards of you for damage; elites and bosses below 20% health take triple damage. Every normal enemy within 40 yards below 20% health dies instantly. Kills Enrage you: 25% Haste for 4 sec.', 24316, 1, 2500, 10, 10, 1, 1, 0, 0, 305, 0, 0, 0, 11, 20, 0, 1, 0, 0, 3, 0, 20, 2097152, 0, 0, 0, 0, 0),
